def _put_trust_anchor_status(
    self, tenant: str, did: str, key_version: str
) -> None:
    # 请求体必须恰为 {"status": "revoked"}；路径 key_version
    # 须为非布尔正整数（路径参数为字符串）。
    data = self._read_json()
    if "status" not in data:
        raise ValidationError("缺少字段: status")
    extra = sorted(set(data) - {"status"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    if data["status"] != "revoked":
        raise ValidationError(
            f"字段 status 非法: {data['status']!r}（仅支持 revoked）"
        )
    if (
        not key_version
        or any(ch < "0" or ch > "9" for ch in key_version)
        or int(key_version) < 1
    ):
        raise ValidationError("路径参数 key_version 必须为正整数")
    record = store.revoke_trust_anchor(tenant, did, int(key_version))
    # 首次吊销与幂等重试均 200，updated_at 保持首次值
    self._send_json(200, self._trust_anchor_payload(record))

def _post_trust_anchor_rotate(
    self, tenant: str, did: str
) -> None:
    # 请求体必须恰含 from_key_version（非布尔正整数）与
    # public_key（可解析的 P-256 PEM）；缺失、多余、类型或
    # PEM 非法一律 400。DID 不存在（含他租户）由 store 判 404。
    data = self._read_json()
    if "from_key_version" not in data:
        raise ValidationError("缺少字段: from_key_version")
    if "public_key" not in data:
        raise ValidationError("缺少字段: public_key")
    extra = sorted(
        set(data) - {"from_key_version", "public_key"}
    )
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    from_key_version = data["from_key_version"]
    if (
        not isinstance(from_key_version, int)
        or isinstance(from_key_version, bool)
        or from_key_version < 1
    ):
        raise ValidationError(
            "字段 from_key_version 必须为正整数"
        )
    record, created = store.rotate_trust_anchor(
        tenant, did, from_key_version, data["public_key"]
    )
    # 新建版本 201；同一前置同 PEM 的幂等重试 200。
    self._send_json(
        201 if created else 200,
        self._trust_anchor_payload(record),
    )

def _post_trust_dids_verify_document(self, tenant: str) -> None:
    # 跨系统 DID 文档验真：公开错误协议，任何失败都返回
    # 200 + {"valid": false, "reason": "<非空中文原因>"}，成功仅
    # {"valid": true}。请求体须恰含 document（JSON 对象）；非法
    # JSON/非对象/缺失/多余字段均为请求类原因。纯只读，不登记
    # 资源、不写历史或审计，跨租户不可探测。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = store.verify_trust_did_document(tenant, data)
    except Exception:  # noqa: BLE001 验真失败绝不暴露内部细节
        self._send_invalid("验真过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "DID 文档验真失败"
    self._send_json(200, payload)

def _post_trust_dids_verify_document_batch(self, tenant: str) -> None:
    # 批量跨系统 DID 文档验真：与单项相同的公开错误协议，任何失败
    # 都返回 HTTP 200。请求体须恰为 {"documents": [文档...]}，
    # 数组非空且不超过 100 项；请求体非法（外层缺失、非法 JSON、

        )
        anchor_status = (
            anchor_row.get("status", "active")
            if anchor_row is not None
            else None
        )
    if anchor_row is None:
        return {
            "valid": False,
            "reason": f"锚点不存在: {issuer_did}#{key_version}",
        }
    if anchor_status == "revoked":
        return {
            "valid": False,
            "reason": f"锚点已吊销: {issuer_did}#{key_version}",
        }
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return {
            "valid": False,
            "reason": (
                f"锚点公钥不可用: {issuer_did}#{key_version}"
                " 不是合法 P-256 公钥"
            ),
        }

    # ---- 签名（覆盖 body 的规范化 JSON）----
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return {
            "valid": False,
            "reason": "签名格式错误: 不是合法的 ES256 签名编码",
        }
    except crypto.InvalidSignature:
        return {
            "valid": False,
            "reason": "签名校验失败，状态正文或签名可能被改动",
        }
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return {"valid": False, "reason": "签名校验失败: 验签过程发生内部错误"}

    # ---- 持久化（双键隔离、严格更新、重放幂等、原子审计）----
    with self._lock:
        bucket = self._ensure_bucket_locked(tenant_id)
        sync_map = bucket.setdefault("credential_status_sync", {})
        issuer_map = sync_map.setdefault(issuer_did, {})
        existing = issuer_map.get(credential_id)
        if existing is not None:
            existing_dt = _parse_utc_z(existing["updated_at"])
            if incoming_dt == existing_dt:
                identical = (
                    existing.get("status") == status
                    and int(existing.get("issuer_key_version"))
                    == key_version
                    and existing.get("reason") == reason
                )
                if identical:
                    # 相同重放：200、不替换、不重复审计
                    return {
                        "valid": True,
                        "status_code": 200,
                        "record": self._sync_status_record(
                            issuer_did, credential_id, existing
                        ),
                    }
                # 同时间不同内容：冲突，不写入、不记审计
                raise ConflictError(
                    "凭证状态 updated_at 相同但内容不同: "
                    f"{issuer_did}#{credential_id}@{updated_at}"
                )
            if incoming_dt < existing_dt:
                # 更早的状态：忽略，保持既有值，200 且不记审计
                return {
                    "valid": True,
                    "status_code": 200,
                    "record": self._sync_status_record(
                        issuer_did, credential_id, existing
                    ),
                }

        # 首次同步（201）或严格更新（200）：替换状态、记审计、追加
        # 历史，三者在同一次原子写落盘（失败一并回滚）。重放、更早
        # 日期、同时间冲突均在上方提前返回，不会追加历史。
        created = existing is None
        new_row = {
            "status": status,
            "updated_at": updated_at,
            "issuer_key_version": key_version,
            "reason": reason,
        }
        snapshot = self._snapshot_locked()
        try:
            issuer_map[credential_id] = new_row
            event = self._append_audit_locked(
                tenant_id,
                AUDIT_TRUST_CREDENTIAL_STATUS_SYNCED,
                "trust_credential_status",
                f"{issuer_did}#{credential_id}",
            )
            entries = self._history_entries_locked(
                bucket, issuer_did, credential_id
            )
            entries.append(
                {
                    "status": status,
                    "reason": reason,
                    "updated_at": updated_at,
                    "issuer_key_version": key_version,
                    "cursor": self._next_history_cursor_locked(),
                    "audit_seq": int(event["seq"]),
                    "audit_timestamp": int(event["timestamp"]),
                }
            )
            self._save_locked()
        except Exception:
            self._restore_locked(snapshot)
            raise
        return {
            "valid": True,
            "status_code": 201 if created else 200,
            "record": self._sync_status_record(
                issuer_did, credential_id, new_row
            ),
        }

